# The methods of str.
s = "  The quick brown fox  "
print(repr(s.strip()), repr(s.lstrip()), repr(s.rstrip()), repr("xxhixx".strip("x")), repr("abcba".strip("ab")))
print(s.split(), "a,b,,c".split(","), "a,b,c".split(",", 1), "a b  c".split(" "), "a,b,c".rsplit(",", 1), "".split(), "".split(","))
print("  a  b  ".split(None, 1), "a\nb\r\nc\rd".splitlines(), "a\nb\n".splitlines(True), "x".split("x"))
print("hello world".title(), "HELLO".lower(), "hello".upper(), "hello world".capitalize(), "Hello".swapcase(), "ß".casefold())
print("hello".replace("l", "L"), "hello".replace("l", "L", 1), "aaa".replace("a", "b", 2), "abc".replace("", "-"))
print("hello".find("l"), "hello".rfind("l"), "hello".find("z"), "hello".find("l", 3), "hello".find("l", -2), "hello".index("e"))
print("hello".startswith("he"), "hello".endswith("lo"), "hello".startswith(("x", "h")), "hello".startswith("l", 2), "hello".endswith("l", 0, 3))
print("123".isdigit(), "12a".isdigit(), "abc".isalpha(), "ab1".isalnum(), "   ".isspace(), "Ab".isupper(), "ab".islower(), "Ab Cd".istitle())
print("½".isnumeric(), "½".isdigit(), "²".isdigit(), "²".isdecimal(), "x1".isidentifier(), "1x".isidentifier(), "abc".isascii(), "é".isascii())
print("a-b-c".partition("-"), "a-b-c".rpartition("-"), "abc".partition("x"), "abc".rpartition("x"))
print("TestCase".removeprefix("Test"), "file.py".removesuffix(".py"), "abc".removeprefix("x"))
print("hello world hello".count("hello"), "aaaa".count("aa"), "abc".count(""), ",".join(map(str, [1, 2, 3])))
print("{} + {} = {}".format(1, 2, 3), "{0}{1}{0}".format("a", "b"), "{name} is {age}".format(name="Ann", age=30))
print("{:>5}|{:<5}|{:^5}|".format("a", "b", "c"), "{0!r} {0!s}".format("x"), "{:.2f}".format(3.14159), "{:,}".format(1234567))
print("{0[1]} {1[key]} {2.real}".format([10, 20], {"key": "v"}, 3 + 4j), "{{literal}} {}".format("x"))
table = str.maketrans("abc", "xyz", "d")
print("abcdabcd".translate(table), "hello".translate({ord("l"): None, ord("h"): "J"}))
print("%-5s|%5s|%05d|%+d|%.3f|%e|%x|%X|%o|%c|%%|%r" % ("ab", "cd", 42, 7, 2.5, 12345.678, 255, 255, 8, 65, "q"))
print("%(a)s and %(b)d" % {"a": "x", "b": 5}, "%s" % (1,), "%s %s" % ("a", "b"), "%5.1f%%" % 99.44, "%g %g %g" % (1e-5, 123456789.0, 0.5))
print("a" * 3 + "b".join(["1", "2"]), "x".join([]), " ".join(["single"]))
